const fs = require('fs');
const readline = require('readline');
const path = require('path');

const brainDir = 'C:/Users/admin/.gemini/antigravity-ide/brain';
const conversations = [
  'fe5f3da4-28e8-4953-b097-ce64bd94b483',
  '53b57104-e4e2-40d0-adc5-813cc565893f'
];

async function searchTranscript() {
  for (const conv of conversations) {
    const transcriptPath = path.join(brainDir, conv, '.system_generated', 'logs', 'transcript_full.jsonl');
    if (!fs.existsSync(transcriptPath)) continue;

    console.log(`\n=================== Transcript: ${conv} ===================`);
    const fileStream = fs.createReadStream(transcriptPath);
    const rl = readline.createInterface({
      input: fileStream,
      crlfDelay: Infinity
    });

    for await (const line of rl) {
      if (!line.trim()) continue;
      const step = JSON.parse(line);

      // Search inside the step object (either tool calls, content, or system output)
      const lineStr = JSON.stringify(step);
      if (lineStr.includes('router.get(\'/:id\'') || lineStr.includes('router.get("/:id"') || lineStr.includes('purchaseLedger.findFirst')) {
        console.log(`[Step ${step.step_index}] Match found (source: ${step.source}, type: ${step.type})`);

        // Print some details of tool calls
        if (step.tool_calls) {
          step.tool_calls.forEach(tc => {
            console.log(`  Tool Call: ${tc.name}`);
            if (tc.args && tc.args.TargetFile) {
              console.log(`    File: ${tc.args.TargetFile}`);
            }
          });
        }
      }
    }
  }
}

searchTranscript().catch(err => {
  console.error(err);
});
